#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
场景名 -> 三色渐变配方（静态氛围色），按设备真实能力自适应出码

为什么要自适应：同一句「热带海岸」，发到 RGB 灯带（WS281x / PWM）只能给 3 通道，
发到 RGBCCT 灯带（主推 WS2805 五色）必须给 4 通道 + cct，否则白通道全程为 0，
看起来发灰、亮度损失一半。

判定依据不用 IC 型号，用固件自己上报的能力位（`/json/info` → `info.leds.lc`，
源码 `wled00/FX_fcn.cpp` `refreshLightCapabilities()`）：
    0x01 = RGB    0x02 = W(白通道)    0x04 = CCT(色温)
这样 PWM / WS281x / WS2805 / SM16825 / SK6812 全部走同一条逻辑，
不会因为换一款灯带或升级固件而失效。

渲染方式（源码依据见 references/scene-palettes.md）：
  fx 161 Shimmer + sx=0    -> position 锁死在段中心，真正静止
  pal 4 = (ter, sec, prim) -> col[2]=起点色, col[1]=中间色, col[0]=终点色
  c1 = 255                 -> radius ≈ 2×SEGLEN，整条都在带内

用法：
    python3 scene_palette.py --list
    python3 scene_palette.py --probe                 # 看目标设备能力（灯数/通道/色温）
    python3 scene_palette.py "热带海岸"               # 出配方 JSON
    python3 scene_palette.py "热带海岸" --apply       # 探测能力 -> 校验灯数 -> 下发
    python3 scene_palette.py "热带海岸" --ip <ip> --apply
    python3 scene_palette.py --off                   # 熄灯 + 归还 UDP 同步设置
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import tempfile
import urllib.request
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
SKILL_DIR = SCRIPT_DIR.parent
CONFIG_PATH = SKILL_DIR / "config.json"
CACHE_PATH = SCRIPT_DIR / ".wled_cache.json"
DEFAULT_LEDS = 70

# 场景表：名字 -> (起点色, 终点色, 默认亮度, 别名)
SCENES: dict[str, tuple[str, str, int, tuple[str, ...]]] = {
    "红苹果":     ("#DC2626", "#FF6B6B", 200, ("苹果", "果红", "果实")),
    "热带海岸":   ("#00B4D8", "#FFD166", 210, ("海边日落", "海岛", "马尔代夫", "沙滩日落", "热带")),
    "春日樱花":   ("#FFB7C5", "#FFF5E6", 190, ("樱花", "春天", "赏樱", "粉色浪漫")),
    "蓝白幻想":   ("#0095D9", "#FFFFFF", 210, ("卡通", "蓝白", "梦幻蓝")),
    "多巴胺治愈": ("#FF9A76", "#FFEAA7", 200, ("治愈", "温馨", "生日", "暖调", "多巴胺")),
    "森林晨光":   ("#42802B", "#91D099", 195, ("森林", "晨光", "绿意", "自然")),
    "日出朝霞":   ("#F3541C", "#F1AB27", 210, ("日出", "朝霞", "晨曦", "黄昏")),
    "深海珍珠":   ("#2D63AD", "#05A99E", 200, ("深海", "海底", "静谧蓝")),
    "极光之夜":   ("#A1B1C8", "#C8C2CC", 185, ("极光", "科幻", "冷调", "银紫")),
    "金色年华":   ("#556A95", "#FFC044", 205, ("金色", "高级感", "轻奢")),
    "秋日枫叶":   ("#A8EFFE", "#F25431", 200, ("秋天", "枫叶", "秋意")),
    "冰川幽蓝":   ("#88B2ED", "#D9F3FD", 190, ("冰川", "冰蓝", "清爽", "冷白")),
    "萤火虫夜":   ("#95FF89", "#EDF468", 185, ("萤火虫", "荧光", "夜景", "嫩黄")),
    "玫瑰花语":   ("#EF6A85", "#FFC6C5", 195, ("玫瑰", "浪漫", "粉红", "告白")),
}


# ---------------------------------------------------------------- HTTP / 设备
def _get(ip: str, path: str, timeout: float = 4.0) -> dict:
    with urllib.request.urlopen(f"http://{ip}{path}", timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8"))


def _post(ip: str, payload: dict, timeout: float = 5.0) -> str:
    req = urllib.request.Request(
        f"http://{ip}/json/state",
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        method="POST",
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode("utf-8")


def resolve_ip(explicit: str | None) -> str:
    """优先级：--ip > 技能发现器（带健康检查）> 缓存 > config.json"""
    if explicit:
        return explicit.strip()
    try:
        if str(SCRIPT_DIR) not in sys.path:
            sys.path.insert(0, str(SCRIPT_DIR))
        import discover_wled
        ip = discover_wled.resolve_ip()
        if ip:
            return ip
    except Exception:
        pass
    try:
        return str(json.loads(CACHE_PATH.read_text(encoding="utf-8"))["ip"])
    except Exception:
        pass
    try:
        return str(json.loads(CONFIG_PATH.read_text(encoding="utf-8"))["wled"]["ip"])
    except Exception:
        return ""


def probe(ip: str) -> dict:
    """读设备真实能力。不猜 IC，只看固件上报的 lc 能力位。"""
    info = _get(ip, "/json/info")
    leds = info.get("leds") or {}
    lc = int(leds.get("lc") or 0)
    try:
        cfg = _get(ip, "/json/cfg")
        ins = ((cfg.get("hw") or {}).get("led") or {}).get("ins") or []
    except Exception:
        ins = []
    first = ins[0] if ins else {}
    led_type = int(first.get("type", -1)) if first.get("type") is not None else -1
    is_pwm = 41 <= led_type <= 47
    return {
        "ip": ip,
        "ver": info.get("ver"),
        "type_kind": "PWM(不可寻址)" if is_pwm else ("IC(可寻址)" if 0 < led_type < 40 else "未知"),
        "is_ic": 0 < led_type < 40,
        "is_pwm": is_pwm,
        "count": int(leds.get("count") or 0),
        "lc": lc,
        "has_rgb": bool(lc & 0x01),
        "has_w": bool(lc & 0x02),
        "has_cct": bool(lc & 0x04),
        "type": first.get("type"),
        "order": first.get("order"),
        "rgbwm": first.get("rgbwm"),
    }


def channels_label(caps: dict) -> str:
    parts = []
    if caps["has_rgb"]:
        parts.append("RGB")
    if caps["has_w"]:
        parts.append("W")
    if caps["has_cct"]:
        parts.append("CCT")
    return "+".join(parts) if parts else "未知"


def format_caps(caps: dict) -> str:
    return (f"{caps['ip']}  WLED {caps['ver']}  {caps['count']} 颗  "
            f"{channels_label(caps)} (lc=0x{caps['lc']:02X})  "
            f"{caps.get('type_kind', '?')}  type={caps['type']} order={caps['order']}")


# ---------------------------------------------------------------- 颜色工具
def hex_to_rgb(value: str) -> tuple[int, int, int]:
    s = value.strip().lstrip("#")
    if len(s) == 3:
        s = "".join(ch * 2 for ch in s)
    if len(s) != 6:
        raise ValueError(f"颜色格式不对：{value!r}（要 #RRGGBB）")
    return int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16)


def rgb_to_hex(rgb: tuple[int, int, int]) -> str:
    return "#%02X%02X%02X" % rgb


def midpoint(a: tuple[int, int, int], b: tuple[int, int, int]) -> tuple[int, int, int]:
    """线性光空间取中点。

    不走 HSV：色相"最短路径"会跑出歧义结果 —— 蓝(#00B4D8)→金(#FFD166) 的色相最短
    路径经过绿色，会得到一块荧光绿，完全不是「海边日落」。光混合是加性的，
    线性光平均才是物理上正确的中间色（得到 #BAC3AB 雾感灰绿）。
    """
    def to_linear(c: int) -> float:
        return (c / 255.0) ** 2.2

    def to_srgb(x: float) -> int:
        return round(255 * (max(0.0, min(1.0, x)) ** (1 / 2.2)))

    return tuple(  # type: ignore[return-value]
        to_srgb((to_linear(x) + to_linear(y)) / 2) for x, y in zip(a, b)
    )


def split_white(rgb: tuple[int, int, int]) -> tuple[tuple[int, int, int], int]:
    """把颜色拆成「彩色分量 + 白通道分量」。

    白通道取三通道最小值（无色/灰的那部分），RGB 减去它。
    这样色相不变、又真的用上白灯珠；纯色（如纯蓝）白通道自然为 0。
    """
    w = min(rgb)
    return tuple(c - w for c in rgb), w  # type: ignore[return-value]


def cct_for(rgb: tuple[int, int, int]) -> int:
    """用色温滑杆还原白通道的冷暖：偏红→暖(大)，偏蓝→冷(小)，中性 127。"""
    return max(0, min(255, round(127 + (rgb[0] - rgb[2]) * 0.5)))


# 颜色名兜底：用户直接说颜色（中英文）时不必落进场景表。
# 纯色 = 三个槽给同一个颜色，pal 4 渲染出来就是平色。
COLOR_NAMES: dict[str, str] = {
    "红": "#FF0000", "红色": "#FF0000", "大红": "#FF0000", "red": "#FF0000",
    "橙": "#FF6A00", "橙色": "#FF6A00", "orange": "#FF6A00",
    "黄": "#FFD400", "黄色": "#FFD400", "yellow": "#FFD400",
    "绿": "#00C832", "绿色": "#00C832", "green": "#00C832",
    "青": "#00C8C8", "青色": "#00C8C8", "cyan": "#00C8C8", "teal": "#00C8C8",
    "蓝": "#0060FF", "蓝色": "#0060FF", "blue": "#0060FF",
    "紫": "#7A00FF", "紫色": "#7A00FF", "purple": "#7A00FF", "violet": "#7A00FF",
    "粉": "#FF7FA8", "粉色": "#FF7FA8", "pink": "#FF7FA8",
    "白": "#FFFFFF", "白色": "#FFFFFF", "white": "#FFFFFF",
    "暖白": "#FFD9A0", "warmwhite": "#FFD9A0", "warm white": "#FFD9A0",
    "冷白": "#E8F2FF", "coolwhite": "#E8F2FF", "cool white": "#E8F2FF",
    "中性白": "#FFF4E8", "neutral white": "#FFF4E8",
    "琥珀": "#FFB000", "amber": "#FFB000",
    "金": "#FFC044", "金色": "#FFC044", "gold": "#FFC044",
}


# ---------------------------------------------------------------- 场景解析
def resolve(query: str) -> tuple[str, str, str, int]:
    """返回 (显示名, 起点色, 终点色, 默认亮度)。找不到抛 KeyError。

    解析顺序：场景名精确 → 颜色名精确 → 场景别名/子串 → 反向子串。
    颜色名优先于别名，避免「红」被某个场景的别名误吞。
    """
    q = query.strip().replace(" ", "")
    if not q:
        raise KeyError("场景名为空")
    if q in SCENES:
        start, end, bri, _ = SCENES[q]
        return q, start, end, bri

    c = COLOR_NAMES.get(q) or COLOR_NAMES.get(q.lower())
    if c:
        return f"纯色 {q}", c, c, 200

    hits = [n for n, (_, _, _, al) in SCENES.items()
            if q in n or any(q in a or a in q for a in al)]
    if not hits:
        hits = [n for n in SCENES if n in q]
    if len(hits) == 1:
        start, end, bri, _ = SCENES[hits[0]]
        return hits[0], start, end, bri
    if len(hits) > 1:
        raise KeyError(f"「{query}」命中多个场景：{'、'.join(hits)}，请说完整名字")
    raise KeyError(f"没有「{query}」这个场景或颜色。用 --list 看全部 {len(SCENES)} 个场景")


# ---------------------------------------------------------------- 配方生成
def build_segment(start_hex: str, end_hex: str, leds: int, profile: str,
                  mid_hex: str | None, caps: dict | None) -> dict:
    a = hex_to_rgb(start_hex)
    b = hex_to_rgb(end_hex)
    mid = hex_to_rgb(mid_hex) if mid_hex else midpoint(a, b)

    # pal 4 = (ter, sec, prim) —— 起点 col[2]，中间 col[1]，终点 col[0]
    stops = (b, mid, a)
    has_w = bool(caps and caps.get("has_w"))
    has_cct = bool(caps and caps.get("has_cct"))

    col: list[list[int]] = []
    whites: list[int] = []
    for c in stops:
        if has_w:
            rgb3, w = split_white(c)
            col.append([*rgb3, w])
            whites.append(w)
        else:
            col.append([*c])

    seg: dict = {
        "start": 0,
        "stop": leds,
        "fx": 161,          # Shimmer：sx=0 时位置锁死，整条铺满调色板
        "sx": 0 if profile == "still" else 40,
        "ix": 0,            # Interval 是「跑完一趟后的停顿」，静止档无意义
        "pal": 4,           # Color Gradient（混合渐变，不是三段分明）
        "c1": 255,          # 带宽拉满：radius ≈ 2×SEGLEN，整条都在带内
        "c2": 0,
        "bri": 255,
        "mi": False,
        "of": 0,
        "bm": 0,
        "o1": False,
        "o2": False,
        "o3": False,
        "col": col,
    }
    if has_cct:
        # cct 是段级参数：取白通道最强的那一档定冷暖（那里白灯珠占比最大）
        warmest = stops[whites.index(max(whites))] if whites else mid
        seg["cct"] = cct_for(warmest)
    return seg


def build_recipe(name: str, start_hex: str, end_hex: str, leds: int, bri: int,
                 profile: str, mid_hex: str | None, caps: dict | None) -> dict:
    seg = build_segment(start_hex, end_hex, leds, profile, mid_hex, caps)
    design = {
        "mode": "静态氛围色（不是 1 分钟动态配方）",
        "palette": f"起点 {start_hex} → 中间 {rgb_to_hex(tuple(seg['col'][1][:3]))} → 终点 {end_hex}",
        "render": ("Shimmer sx=0：position=(SEGLEN<<7) 锁死在段中心，静止"
                   if profile == "still" else "Shimmer sx=40：极慢呼吸推移"),
        "ordering": "pal 4 = (ter, sec, prim) ⇒ col[2]=起点、col[1]=中间、col[0]=终点",
        "coverage": f"单段 0..{leds}，整条覆盖",
    }
    if caps:
        design["device"] = format_caps(caps)
        design["channels"] = (f"{channels_label(caps)}；按 lc 能力位自适应出码"
                              f"（0x01=RGB 0x02=W 0x04=CCT）")
    return {
        "name": f"场景 · {name}",
        "type": "static-ambient",
        "bri": bri,
        "colors": seg["col"],
        "segments": [seg],
        "_design": design,
    }


def emit_state(recipe: dict) -> dict:
    seg = dict(recipe["segments"][0])
    seg["id"] = 0
    return {"on": True, "bri": recipe["bri"], "transition": 0, "seg": [seg]}


# ---------------------------------------------------------------- 下发 / 收尾
def apply_via_gateway(recipe: dict, dry_run: bool, ip: str) -> int:
    fd, tmp = tempfile.mkstemp(prefix="scene-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(recipe, f, ensure_ascii=False, indent=2)
        cmd = [sys.executable, str(SCRIPT_DIR / "apply_recipe.py"), tmp, "--ip", ip]
        if dry_run:
            cmd.append("--dry-run")
        return subprocess.call(cmd, cwd=str(SKILL_DIR))
    finally:
        try:
            os.unlink(tmp)
        except OSError:
            pass


def teardown(ip: str) -> int:
    """熄灯 + 归还被 apply 改过的 UDP 同步接收（Rule 11）。"""
    rc = 0
    try:
        _post(ip, {"on": False, "live": False})
        print(f"  已熄灯 {ip}（on=false, live=false）")
    except Exception as exc:
        print(f"  熄灯失败：{exc}", file=sys.stderr)
        rc = 1
    r = subprocess.run([sys.executable, str(SCRIPT_DIR / "apply_recipe.py"), "--release"],
                       cwd=str(SKILL_DIR), capture_output=True, text=True)
    if "已恢复" in (r.stdout or ""):
        print("  已归还 UDP 同步接收设置")
    else:
        print(f"  release 未确认：{(r.stdout or r.stderr).strip()[-200:]}", file=sys.stderr)
        rc = rc or 1
    return rc


def main() -> int:
    ap = argparse.ArgumentParser(
        description="场景名 -> 三色渐变配方（按设备能力自适应 RGB / RGBW / RGBCCT）",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    ap.add_argument("scene", nargs="?", help="场景名或别名，例如 热带海岸 / 樱花 / 生日")
    ap.add_argument("--list", action="store_true", help="列出全部场景")
    ap.add_argument("--probe", action="store_true", help="只读设备能力（灯数/通道/色温）后退出")
    ap.add_argument("--ip", default=None, help="目标 WLED IP，默认用发现器解析")
    ap.add_argument("--emit", choices=("recipe", "state"), default="recipe",
                    help="recipe = 完整配方（默认）；state = 可直接 POST 的 /json/state 片段")
    ap.add_argument("--bri", type=int, default=None, help="全局亮度 1..255，默认取场景值")
    ap.add_argument("--leds", type=int, default=None,
                    help="灯珠数；默认跟随设备实际值（探测失败才退回 70）")
    ap.add_argument("--mid", default=None, help="手动指定中间色 #RRGGBB")
    ap.add_argument("--profile", choices=("still", "breath"), default="still",
                    help="still = 完全静止（默认）；breath = 极慢呼吸")
    ap.add_argument("--apply", action="store_true", help="探测能力 -> 校验灯数 -> 下发")
    ap.add_argument("--off", action="store_true", help="熄灯 + 归还 UDP 同步设置后退出")
    ap.add_argument("--dry-run", action="store_true", help="配合 --apply：只打印不写入")
    args = ap.parse_args()

    ip = resolve_ip(args.ip)

    if args.list or (not args.scene and not args.probe and not args.off):
        print(f"{len(SCENES)} 个场景（起点 → 终点）：")
        for n, (s, e, b, al) in SCENES.items():
            print(f"  {n:<8} {s} → {e}  bri≈{b}  别名：{'、'.join(al)}")
        return 0

    if args.off:
        if not ip:
            print("错误：找不到设备，用 --ip 指定", file=sys.stderr)
            return 1
        return teardown(ip)

    caps: dict | None = None
    if ip:
        try:
            caps = probe(ip)
        except Exception as exc:
            print(f"提示：探测 {ip} 失败（{type(exc).__name__}），按纯 RGB 出码", file=sys.stderr)
    else:
        print("提示：未解析到设备 IP，按纯 RGB 出码；--apply 需要 --ip", file=sys.stderr)

    if args.probe:
        if not caps:
            print("错误：探测失败，无法读取能力", file=sys.stderr)
            return 1
        print(format_caps(caps))
        print(f"  出码：{'4 通道 (R,G,B,W) + cct' if caps['has_w'] else '3 通道 (R,G,B)'}")
        return 0

    # 灯数：优先跟随设备实际值，避免「70 颗的模板打到 490 颗的灯上」
    leds = args.leds
    if leds is None:
        leds = caps["count"] if caps and caps["count"] > 1 else DEFAULT_LEDS
    if args.apply and caps and caps["count"] > 1 and leds != caps["count"]:
        print(f"错误：配方灯数 {leds} ≠ 设备实际灯数 {caps['count']}（{ip}）\n"
              f"      大概率选错灯带了。确认后重跑，或去掉 --leds 让它跟随设备。",
              file=sys.stderr)
        return 1

    try:
        name, start_hex, end_hex, scene_bri = resolve(args.scene)
    except KeyError as exc:
        print(f"错误：{exc}", file=sys.stderr)
        return 1

    bri = max(1, min(255, args.bri if args.bri else scene_bri))
    if args.mid:
        try:
            hex_to_rgb(args.mid)
        except ValueError as exc:
            print(f"错误：--mid {exc}", file=sys.stderr)
            return 1

    recipe = build_recipe(name, start_hex, end_hex, leds, bri, args.profile, args.mid, caps)

    if args.apply:
        if not ip:
            print("错误：--apply 需要设备 IP（--ip 或先跑 discover_wled.py）", file=sys.stderr)
            return 1
        print(f"目标：{format_caps(caps)}" if caps else f"目标：{ip}")
        return apply_via_gateway(recipe, args.dry_run, ip)

    payload = recipe if args.emit == "recipe" else emit_state(recipe)
    print(json.dumps(payload, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())
# AI: end
